<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {toWorld,type Position} from '../geography.ts';
import GateGps from './GateGps.vue';
defineEmits<{close:[]}>();
const references=ref<any>(),ownerVisible=ref(true),missingVisible=ref(true);
const data=ref<any>(),error=ref(''),span=ref(550),center=ref({x:0,z:0}),selected=ref<any>();
const enabled=ref<Record<string,boolean>>({osm:true,'overture-buildings':false,'overture-transportation':true,'overture-base':false,'overture-places':true,microsoft:false});
const origin:Position=[9.777370,7.843357];
const bounds=computed(()=>`${center.value.x-span.value/2} ${center.value.z-span.value/2} ${span.value} ${span.value}`);
const layers=computed(()=>data.value?.layers??[]);
const visible=computed(()=>layers.value.filter((l:any)=>enabled.value[l.id]).flatMap((l:any)=>l.features.map((f:any)=>({...f,layer:l.id,color:l.color,licence:l.license}))).filter((f:any)=>{const pts=coordinates(f.geometry);if(!pts.length)return false;const b=pts.reduce((b,p)=>[Math.min(b[0]!,p.x),Math.max(b[1]!,p.x),Math.min(b[2]!,p.z),Math.max(b[3]!,p.z)],[Infinity,-Infinity,Infinity,-Infinity]);return b[0]!<=center.value.x+span.value/2&&b[1]!>=center.value.x-span.value/2&&b[2]!<=center.value.z+span.value/2&&b[3]!>=center.value.z-span.value/2;}));
function coordinates(g:any):{x:number;z:number}[]{if(g.type==='Point')return[toWorld(origin,g.coordinates)];if(g.type==='LineString')return g.coordinates.map((p:Position)=>toWorld(origin,p));if(g.type==='Polygon')return g.coordinates[0].map((p:Position)=>toWorld(origin,p));if(g.type==='MultiPolygon')return g.coordinates.flatMap((p:any)=>p[0].map((q:Position)=>toWorld(origin,q)));return [];}
function path(g:any){const rings=g.type==='MultiPolygon'?g.coordinates.flatMap((p:any)=>p):g.type==='Polygon'?g.coordinates:[g.coordinates];return rings.map((r:any)=>r.map((p:Position,i:number)=>{const q=toWorld(origin,p);return `${i?'L':'M'}${q.x},${q.z}`;}).join(' ')+(g.type.includes('Polygon')?'Z':'')).join(' ');}
onMounted(async()=>{try{const [r,q]=await Promise.all([fetch('/fuw-open.json'),fetch('/fuw-reference-review.json')]);if(!r.ok||!q.ok)throw Error('FUW review unavailable');data.value=await r.json();references.value=await q.json();center.value={x:-285,z:170};span.value=1100;}catch(e){error.value=String(e);}});
</script>
<template><section class="campus-overview" aria-label="FUW independent geography review"><header><div><small>FUW · INDEPENDENT DATA REVIEW</small><h2>From gate report to grounded campus</h2><p>Orange cross: earlier owner pin. Purple diamonds: updated owner Google Earth reports, not GPS surveys. Provider geometry stays separate; no official gate position or campus boundary is verified.</p></div><button @click="$emit('close')">Close campus overview</button></header><p v-if="error" role="alert">{{error}}</p><template v-if="data"><div class="campus-layout"><div><div class="map-tools"><label>View {{span}}m <input type="range" aria-label="Campus view width" min="100" max="3400" step="25" v-model.number="span"></label><button v-for="[label,x,z] in [['North',0,-1],['West',-1,0],['East',1,0],['South',0,1]]" :key="label" @click="center={x:center.x+Number(x)*span/3,z:center.z+Number(z)*span/3}">{{label}}</button><button @click="center={x:-285,z:170};span=1100">All references</button><button v-for="m in references?.markers??[]" :key="m.id" @click="center=m.point;span=260">{{m.name}}</button></div><svg :viewBox="bounds" aria-label="Independent FUW-area road and footprint overview"><rect :x="center.x-span/2" :y="center.z-span/2" :width="span" :height="span" fill="#edf0e4"/><g v-for="f in visible" :key="f.layer+f.id" @click="selected=f"><circle v-if="f.geometry.type==='Point'" :cx="coordinates(f.geometry)[0]?.x" :cy="coordinates(f.geometry)[0]?.z" :r="span/240" :fill="f.color"/><path v-else :d="path(f.geometry)" :fill="f.geometry.type.includes('Polygon')?f.color:'none'" :fill-opacity=".35" :stroke="f.color" :stroke-width="f.geometry.type.includes('Polygon')?span/1500:span/550"/><title>{{f.layer}} · {{f.id}}</title></g><g v-if="ownerVisible" class="owner-reference-layer"><g v-for="m in references?.markers??[]" :key="m.id" class="owner-marker" @click="selected={layer:'owner-reference',...m}"><path :d="`M${m.point.x},${m.point.z-span/140}l${span/140},${span/140}l${-span/140},${span/140}l${-span/140},${-span/140}Z`" fill="#922d94" stroke="#fff" :stroke-width="span/1000"/><text v-if="m.id!=='earlier-marker'||span<150" :x="m.point.x+span/90" :y="m.point.z-span/90" :font-size="span/70" fill="#702477">{{m.name}} ?</text><title>{{m.name}} ? owner report, not GPS</title></g></g><path d="M-6,0L6,0M0,-6L0,6" stroke="#d95c16" stroke-width="2"/><circle cx="0" cy="0" r="11" fill="none" stroke="#d95c16" stroke-dasharray="2 2"/><text :x="center.x-span*.46" :y="center.z-span*.43" :font-size="span/40" fill="#214938">N ↑</text><line :x1="center.x-span*.46" :x2="center.x-span*.46+100" :y1="center.z+span*.44" :y2="center.z+span*.44" stroke="#214938" :stroke-width="span/700"/><text :x="center.x-span*.46" :y="center.z+span*.41" :font-size="span/60">100m local display scale</text></svg><p>Click a source feature to inspect its ID, provenance and confidence. Overlay colors identify providers, not university ownership. Footprints are not moved or merged.</p></div><aside><h3>Owner reports and gaps</h3><label class="reference-toggle"><input type="checkbox" v-model="ownerVisible" aria-label="Owner reference layer"> Owner reports ? not independently verified</label><label class="reference-toggle"><input type="checkbox" v-model="missingVisible" aria-label="Missing information layer"> Missing information ? no invented positions</label><p v-if="references">The new main-gate report is {{references.comparison.mainVsPreviousPinM.toFixed(2)}}m from the earlier pin and lies inside anonymous OSM footprint {{references.comparison.mainInsideBuildingIds.join(', ')}}. The gameplay gate has not been moved to that point.</p><h3>Independent source layers</h3><label v-for="l in layers" :key="l.id" class="layer"><input type="checkbox" v-model="enabled[l.id]"><span :style="{color:l.color}">{{l.title}}</span> ({{l.features.length}})<small>{{l.license}} · {{l.note}}</small></label><h3>Selected source record</h3><pre v-if="selected">{{JSON.stringify(selected,null,2)}}</pre><p v-else>No feature selected.</p><div v-if="missingVisible" class="missing-information-layer"><h3>Missing information</h3><p>Main and second gates now have owner-reported points, not verified entrances. ICT's point is inside a sourced footprint, which does not independently establish its identity. Public access, campus boundaries and actual dimensions remain unknown.</p><p v-for="m in references?.missing??[]" :key="m.name" class="missing-location">{{m.name}}: {{m.status}}</p></div><p>{{references?.conclusion}}</p><a href="/fuw-reference-data.md" target="_blank">Reference comparison and GPS/photo checklist</a><GateGps/><h3>Attribution and source offer</h3><p v-for="s in data.sources" :key="s.title"><a :href="s.url" target="_blank" rel="noreferrer">{{s.title}}</a><small>{{s.note}}</small></p><a href="/fuw-data.md" target="_blank">Data, licenses and reproducibility</a></aside></div></template></section></template>
<style scoped>.campus-overview{position:absolute;inset:10px;z-index:15;background:#fbfcf4;border:1px solid #bdc9b1;border-radius:12px;padding:20px;overflow:auto;font-size:12px;color:#244b3d}.campus-overview header{display:flex;justify-content:space-between;gap:24px}.campus-overview h2{margin:8px 0;font-size:24px}.campus-overview p{line-height:1.6}.campus-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px}.campus-overview svg{width:100%;height:58vh;cursor:crosshair;border:1px solid #b8c8ad}.campus-overview button{min-height:40px;border:1px solid #9eaf94;border-radius:7px;background:#e5eeda;padding:8px;color:#244b3d}.map-tools{display:flex;flex-wrap:wrap;align-items:center;gap:5px;margin:8px 0}.map-tools input{max-width:130px}.layer{display:block;margin:12px 0;line-height:1.5}.campus-overview small{display:block;font-size:10px;line-height:1.6}.campus-overview aside{overflow-wrap:anywhere}.campus-overview pre{font-size:10px;max-height:220px;overflow:auto;white-space:pre-wrap;background:#eff2e6;padding:10px}.campus-overview input[type=checkbox]{min-width:20px;min-height:20px;vertical-align:middle}@media(max-width:750px){.campus-overview{padding:12px}.campus-overview header{display:block}.campus-layout{display:block}.campus-overview svg{height:46vh}.campus-overview h2{font-size:20px}}</style>

<style scoped>.reference-toggle{display:block;padding:8px 0;line-height:1.6;color:#75377d}.owner-marker{cursor:pointer}.missing-information-layer{border-left:3px solid #a79878;padding-left:10px}.missing-location{font-size:11px}</style>
